double mlp_loss_and_grad(const double* params, int n_in, int n_hidden,
                         const double* X, const double* y, int n_samples,
                         double* grad) {
    const double* W1 = params;
    const double* b1 = params + n_hidden * n_in;
    const double* W2 = b1 + n_hidden;
    const double b2 = W2[n_hidden];

    double* gW1 = grad;
    double* gb1 = grad + n_hidden * n_in;
    double* gW2 = gb1 + n_hidden;
    double* gb2 = gW2 + n_hidden;

    for (int i = 0; i < n_hidden * n_in; ++i) gW1[i] = 0.0;
    for (int j = 0; j < n_hidden; ++j) { gb1[j] = 0.0; gW2[j] = 0.0; }
    *gb2 = 0.0;

    double loss = 0.0;

    for (int s = 0; s < n_samples; ++s) {
        const double* x = X + s * n_in;

        // Forward pass
        for (int j = 0; j < n_hidden; ++j) {
            double a = b1[j];
            const double* wrow = W1 + j * n_in;
            for (int k = 0; k < n_in; ++k) a += wrow[k] * x[k];
            hbuf[j] = std::tanh(a);
        }
        double z = b2;
        for (int j = 0; j < n_hidden; ++j) z += W2[j] * hbuf[j];
        double p = 1.0 / (1.0 + std::exp(-z));

        // Loss (clamp for numerical safety of log)
        double pc = p < 1e-15 ? 1e-15 : (p > 1.0 - 1e-15 ? 1.0 - 1e-15 : p);
        double ys = y[s];
        loss += -(ys * std::log(pc) + (1.0 - ys) * std::log(1.0 - pc));

        // Backward pass
        double dz = p - ys;
        for (int j = 0; j < n_hidden; ++j) {
            double dh = dz * W2[j];
            double da = dh * (1.0 - hbuf[j] * hbuf[j]);
            double* grow = gW1 + j * n_in;
            const double* wrow = W1 + j * n_in;
            for (int k = 0; k < n_in; ++k) grow[k] += da * x[k];
            gb1[j] += da;
            gW2[j] += dz * hbuf[j];
        }
        *gb2 += dz;
    }

    double inv = 1.0 / static_cast<double>(n_samples);
    for (int i = 0; i < n_hidden * n_in; ++i) gW1[i] *= inv;
    for (int j = 0; j < n_hidden; ++j) { gb1[j] *= inv; gW2[j] *= inv; }
    *gb2 *= inv;

    return loss * inv;
}
